// Authored self-runner for RE-DAMAGE-DISPATCH02 (Phase 1 candidate).
//
// Status: authored but NOT compiled and NOT executed in Phase 1. The runner is
// built only when the primary resumes the task and authorizes direct csc.
//
// The code under test is the private fixture generated by run_dispatch.py:
// the canonical CalculateFormula body with exactly one declared span replaced
// (the missing-key log block), plus the unchanged CalculateHeal and TFormula
// slices and the unchanged prior nine bodies. The fixture classification is
// EXPLICITLY_TRANSFORMED_RECOVERED_SOURCE_FIXTURE and its run state is
// NEVER_RUN as game/runtime evidence.
//
// No test framework, reflection, file, process, network, native, thread, clock
// or RNG API is used. Every input is a synthetic authored vector; no game
// configuration, Buff value or extracted asset is read. Every expected value is
// a hardcoded IEEE-754 bit pattern or an independent literal calculation, never
// a value produced by calling the code under test.
using System;
using System.Collections.Generic;

internal static class Program
{
	private static int _passedGroups;
	private static int _failedGroups;

	private static readonly Dictionary<string, int> GroupAssertions =
		new Dictionary<string, int>(StringComparer.Ordinal);

	private static readonly (string Sid, Action Body)[] Tests =
	{
		("T01", T01_RealTypeZeroHurt),
		("T02", T02_MissingFormulaKey),
		("T03", T03_SeedOrdering),
		("T04", T04_SignedRemainder),
		("T05", T05_NumericDiscriminators),
		("T06", T06_HealAndOtherCalculationTypes),
		("T07", T07_ExceptionAfterSeedStore),
		("T08", T08_RepeatedInvocationAndForwarding)
	};

	private static int Main()
	{
		Console.WriteLine("RE-DAMAGE-DISPATCH02 SELF-RUNNER");
		Console.WriteLine("EXECUTION_PATH=DIRECT_CSC_ASSEMBLY");
		Console.WriteLine("FIXTURE_CLASSIFICATION=EXPLICITLY_TRANSFORMED_RECOVERED_SOURCE_FIXTURE");
		Console.WriteLine("FIXTURE_RUN_STATE=NEVER_RUN");
		Console.WriteLine("CHANGED_SPANS=1_CHANGED_BODY_CALCULATEFORMULA_257_260");
		Console.WriteLine("TESTS_PLANNED=" + Tests.Length.ToString());
		Console.WriteLine("SIDS=" + Sids());

		HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
		foreach ((string sid, Action body) in Tests)
		{
			if (!seen.Add(sid))
			{
				T.Fail("duplicate SID " + sid);
			}
			RunGroup(sid, body);
		}

		int groupsWithAssertions = 0;
		foreach ((string sid, Action _) in Tests)
		{
			if (GroupAssertions.TryGetValue(sid, out int assertions) && assertions > 0)
			{
				groupsWithAssertions++;
				Console.WriteLine("GROUP_ASSERTIONS " + sid + "=" + assertions.ToString());
			}
		}

		const int ExpectedGroups = 8;
		const int MinAssertions = 40;
		const int MaxAssertions = 60;
		bool shapeOk = Tests.Length == ExpectedGroups
			&& seen.Count == ExpectedGroups
			&& groupsWithAssertions == ExpectedGroups;
		bool budgetOk = T.Assertions >= MinAssertions && T.Assertions <= MaxAssertions;

		Console.WriteLine("GROUPS_WITH_ASSERTIONS=" + groupsWithAssertions.ToString());
		Console.WriteLine("GROUPS_PASSED=" + _passedGroups.ToString());
		Console.WriteLine("GROUPS_FAILED=" + _failedGroups.ToString());
		Console.WriteLine("ASSERTIONS_TOTAL=" + T.Assertions.ToString());
		Console.WriteLine("ASSERTIONS_PASSED=" + T.Passed.ToString());
		Console.WriteLine("ASSERTIONS_FAILED=" + T.Failures.ToString());
		Console.WriteLine("ASSERTION_BUDGET=" + MinAssertions.ToString() + ".." + MaxAssertions.ToString());
		Console.WriteLine("ASSERTION_BUDGET_OK=" + (budgetOk ? "true" : "false"));
		Console.WriteLine("SYNTHETIC_INPUTS_ONLY=true");
		Console.WriteLine("RECOMPUTED_FORMULA_ASSERTIONS=0");
		Console.WriteLine("HISTORICAL_RESULT_AGGREGATION=0");
		Console.WriteLine("RE_COVERAGE_COUNT_UPGRADE=0");

		bool ok = shapeOk && budgetOk && _failedGroups == 0 && T.Failures == 0 && T.Assertions > 0;
		Console.WriteLine(ok ? "RESULT=PASS" : "RESULT=FAIL");
		return ok ? 0 : 1;
	}

	private static string Sids()
	{
		string[] parts = new string[Tests.Length];
		for (int i = 0; i < Tests.Length; i++)
		{
			parts[i] = Tests[i].Sid;
		}
		return string.Join(",", parts);
	}

	private static void RunGroup(string sid, Action body)
	{
		Console.WriteLine("TEST " + sid);
		int assertionsBefore = T.Assertions;
		int passedBefore = T.Passed;
		int failuresBefore = T.Failures;
		try
		{
			body();
		}
		catch (Exception ex)
		{
			T.Failures++;
			Console.WriteLine("  UNEXPECTED EXCEPTION " + ex.GetType().Name + ": " + ex.Message);
		}

		int assertions = T.Assertions - assertionsBefore;
		int passed = T.Passed - passedBefore;
		int failed = T.Failures - failuresBefore;
		GroupAssertions[sid] = assertions;

		bool ok = assertions > 0 && failed == 0 && passed == assertions;
		if (ok)
		{
			_passedGroups++;
			Console.WriteLine("RESULT " + sid + " PASS assertions=" + assertions.ToString());
		}
		else
		{
			_failedGroups++;
			Console.WriteLine("RESULT " + sid + " FAIL assertions=" + assertions.ToString()
				+ " passed=" + passed.ToString() + " failed=" + failed.ToString());
		}
	}

	private static void ResetAll()
	{
		Probe.Reset();
		Log.Reset();
		RandomSystem.Reset();
		Calculation.ClearFormulasForTest();
	}

	private static AttributeSnapshot Snap(params (int Index, float Value)[] entries)
	{
		AttributeSnapshot snapshot = new AttributeSnapshot();
		foreach ((int index, float value) in entries)
		{
			snapshot.CurrentValues[index] = value;
		}
		return snapshot;
	}

	private static SnapshotPayload Payload(AttributeSnapshot attacker, AttributeSnapshot target)
	{
		return new SnapshotPayload { AttackerSnapshot = attacker, TargetSnapshot = target };
	}

	// Neutral harness defaults: formula type/calculation type/related property
	// and attack type are supplied by the caller; RateLv={0}, CureBase={0},
	// uniform fluctuation bounds {10000}, ExtraRate=1, Accumulation=0.
	private static TDamageParam Param(int formulaType, int calculateType, int relatedProperty,
		int attackType, int skillLevel, int oldSeed)
	{
		TDamageParam param = new TDamageParam();
		param.SkillLevel = skillLevel;
		param.DamageData.Owner = param;
		param.DamageData.FormulaType = formulaType;
		param.DamageData.CalculateType = calculateType;
		param.DamageData.RelatedProperty = relatedProperty;
		param.DamageData.Type = attackType;
		param.DamageData.RateLvArray = new[] { 0 };
		param.DamageData.CureBaseValueArray = new[] { 0 };
		param.DamageData.FluctuationUpperArray = new[] { 10000 };
		param.DamageData.FluctuationLowerArray = new[] { 10000 };
		param.SetSeedSilently(oldSeed);
		param.ExtraRate = 1f;
		param.Accumulation = 0f;
		return param;
	}

	// T01: real formulaType 0 Hurt invocation reaches the canonical CalculateHurt
	// and the shared seed/fluctuation/ceiling tail.
	private static void T01_RealTypeZeroHurt()
	{
		ResetAll();
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0, 0, 0 });

		TDamageParam first = Param(0, 0, 7, 0, 1, 2);
		AttributeSnapshot attacker = Snap((9, 5000f));
		AttributeSnapshot target = Snap((10, 800f));
		SnapshotPayload payload = Payload(attacker, target);
		double critical = Calculation.CalculateFormula(first, payload, true, 64.0, 0.0, 1.0, 1.0);
		T.Bits("T01a",
			"formulaType=0 calculateType=Hurt rateLv={0} related=7 targetDef=800 attackerCritDamage=5000 crit=true augment=64",
			0x4030000000000000UL, critical);

		TDamageParam second = Param(0, 0, 7, 0, 1, 2);
		double plain = Calculation.CalculateFormula(second, payload, false, 64.0, 0.0, 1.0, 1.0);
		T.Bits("T01b",
			"same vector crit=false => 64*1.0*0.5",
			0x4040000000000000UL, plain);

		TDamageParam third = Param(0, 0, 7, 0, 2, 2);
		third.DamageData.RateLvArray = new[] { 0, 10000 };
		third.DamageData.CureBaseValueArray = new[] { 777 };
		double scaled = Calculation.CalculateFormula(third, Payload(Snap((7, 128f)), Snap()),
			false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T01c",
			"rateLv={0,10000} skillLevel=2 attackerAtk[7]=128 targetDef=0 crit=false augment=0",
			0x4060000000000000UL, scaled);
		T.True("T01d",
			"CureBaseValue() with decoy {777} is never read on the Hurt branch",
			third.DamageData.CureBaseValueReads == 0);
		T.True("T01e",
			"third call provider input (old 2, reason 1) and stored seed 0",
			RandomSystem.Calls == 3
				&& RandomSystem.Inputs[2].Seed == 2
				&& RandomSystem.Inputs[2].Reason == 1
				&& third.PeekSeed() == 0);
	}

	// T02: nonzero formula type with an empty registry logs once and returns
	// +0.0 before any seed read or seed mutation.
	private static void T02_MissingFormulaKey()
	{
		ResetAll();
		RandomSystem.NextSeeds = new Queue<int>(new[] { 5 });
		TDamageParam param = Param(7, 0, 7, 0, 1, 41);
		param.DamageData.Id = 9007199254740993L;
		SnapshotPayload payload = Payload(Snap(), Snap());
		double result = Calculation.CalculateFormula(param, payload, false, 0.0, 0.0, 1.0, 1.0);

		T.Bits("T02a", "formulaType=7 empty registry => +0.0 (not -0.0)", 0x0000000000000000UL, result);
		T.True("T02b", "logger called exactly once", Log.Calls == 1);
		T.True("T02c", "module 35 and author 20", (int)Log.Module == 35 && (int)Log.Author == 20);
		T.True("T02d", "message is the exact canonical literal", Log.Message == "unexpected formula type");
		T.True("T02e", "payload has exactly two entries", Log.Payload.Count == 2);
		T.True("T02f", "entry 0 is (damageId, boxed long 9007199254740993)",
			Log.Payload[0].Key == "damageId"
				&& Log.Payload[0].Value is long
				&& (long)Log.Payload[0].Value == 9007199254740993L);
		T.True("T02g", "entry 1 is (formula type, boxed int 7)",
			Log.Payload[1].Key == "formula type"
				&& Log.Payload[1].Value is int
				&& (int)Log.Payload[1].Value == 7);
		T.True("T02h", "Damage.Id getter traced exactly once", param.DamageData.IdReads == 1);
		T.True("T02i", "seed unchanged and ZERO seed get/provider/bounds reads",
			param.PeekSeed() == 41
				&& param.SeedGets == 0
				&& RandomSystem.Calls == 0
				&& param.DamageData.UpperReads == 0
				&& param.DamageData.LowerReads == 0);

		ResetAll();
		RandomSystem.NextSeeds = new Queue<int>(new[] { 5 });
		Log.ThrowOnError = true;
		TDamageParam throwing = Param(7, 0, 7, 0, 1, 41);
		T.Throws<InvalidOperationException>("T02j", "authored logger throws after capture",
			() => Calculation.CalculateFormula(throwing, payload, false, 0.0, 0.0, 1.0, 1.0));
		T.True("T02k", "logger exception propagates with unchanged seed and no seed read",
			throwing.PeekSeed() == 41 && throwing.SeedGets == 0 && Log.Calls == 1);
	}

	// T03: callback, old-seed read, provider, setter, then bounds. A next-seed
	// bug (using the provider result for the fluctuation remainder) yields 1.
	private static void T03_SeedOrdering()
	{
		ResetAll();
		Calculation.RegisterFormulaForTest(7,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) =>
			{
				Probe.Add("callback");
				return 1.0;
			});
		TDamageParam param = Param(7, 0, 7, 0, 1, 2);
		param.DamageData.FluctuationUpperArray = new[] { 10001 };
		param.DamageData.FluctuationLowerArray = new[] { 10000 };
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0 });
		double result = Calculation.CalculateFormula(param, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T03a",
			"oldSeed=2 next=0 upper=10001 lower=10000 callback=1 => Ceiling(1.0002000331878662)=2; a next-seed bug gives 1",
			0x4000000000000000UL, result);
		T.True("T03b",
			"trace order callback -> old seed -> provider -> setter -> upper -> lower -> ExtraRate, bounds see stored 0",
			Probe.Joined() == "callback;seed.get=2;provider(2,1);seed.set=0;upper(seed=0);lower(seed=0);extraRate(seed=0)");
		T.True("T03c", "provider received exactly (2,1)",
			RandomSystem.Inputs.Count == 1
				&& RandomSystem.Inputs[0].Seed == 2
				&& RandomSystem.Inputs[0].Reason == 1);
		T.True("T03d", "stored seed is 0", param.PeekSeed() == 0);

		Calculation.RegisterFormulaForTest(8,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) =>
			{
				input.RandomSeed = 7;
				return 1.0;
			});
		TDamageParam mutating = Param(8, 0, 7, 0, 1, 2);
		RandomSystem.NextSeeds = new Queue<int>(new[] { 3 });
		Calculation.CalculateFormula(mutating, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.True("T03e",
			"callback seed mutation reaches the old-seed read (provider saw 7) and the new seed 3 is stored",
			RandomSystem.Inputs.Count == 2
				&& RandomSystem.Inputs[1].Seed == 7
				&& mutating.PeekSeed() == 3);
	}

	// T04: C# signed remainder, not a Euclidean modulus.
	private static void T04_SignedRemainder()
	{
		ResetAll();
		Calculation.RegisterFormulaForTest(7,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) => 1.0);
		TDamageParam negativeOne = Param(7, 0, 7, 0, 1, -1);
		negativeOne.DamageData.FluctuationUpperArray = new[] { 10001 };
		negativeOne.DamageData.FluctuationLowerArray = new[] { 10000 };
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0, 0 });
		double first = Calculation.CalculateFormula(negativeOne, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T04a",
			"oldSeed=-1 => -1%10000=-1 => (1*-1+10000)*float(0.0001)=0.9998999834060669 => Ceiling 1; Euclidean 9999 gives 2",
			0x3FF0000000000000UL, first);

		TDamageParam negativeBig = Param(7, 0, 7, 0, 1, -10001);
		negativeBig.DamageData.FluctuationUpperArray = new[] { 10001 };
		negativeBig.DamageData.FluctuationLowerArray = new[] { 10000 };
		double second = Calculation.CalculateFormula(negativeBig, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T04b",
			"oldSeed=-10001 => truncating division also leaves remainder -1 => Ceiling 1",
			0x3FF0000000000000UL, second);
		T.True("T04c", "provider received both signed old seeds with reason 1",
			RandomSystem.Inputs.Count == 2
				&& RandomSystem.Inputs[0].Seed == -1
				&& RandomSystem.Inputs[1].Seed == -10001
				&& RandomSystem.Inputs[1].Reason == 1);
	}

	// T05: numeric discriminators. Expected values are independently derived
	// IEEE-754 literals; no input is produced by the code under test.
	private static void T05_NumericDiscriminators()
	{
		ResetAll();
		Calculation.RegisterFormulaForTest(7,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) => 10000.0001);
		TDamageParam floatFactor = Param(7, 0, 7, 0, 1, 2);
		floatFactor.DamageData.FluctuationUpperArray = new[] { 1 };
		floatFactor.DamageData.FluctuationLowerArray = new[] { 1 };
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0 });
		double first = Calculation.CalculateFormula(floatFactor, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T05a",
			"amount=10000.0001 extra=1 factor=float(0.0001)=9.999999747378752e-05 => product 0.9999999847378749 => Ceiling 1; a double 0.0001 factor gives 1.00000001 => 2",
			0x3FF0000000000000UL, first);

		Calculation.RegisterFormulaForTest(8,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) => 6.666666567325595);
		TDamageParam regroup = Param(8, 0, 7, 0, 1, 2);
		regroup.DamageData.FluctuationUpperArray = new[] { 15000 };
		regroup.DamageData.FluctuationLowerArray = new[] { 15000 };
		regroup.ExtraRate = 0.1f;
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0 });
		double second = Calculation.CalculateFormula(regroup, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T05b",
			"amount bits 0x401AAAAAA4000003=6.666666567325595 extra=float(0.1)=0.10000000149011612 factor=1.5f => left-to-right chain is exactly 1.0; regrouping gives 1.0000000000000002",
			0x3FF0000000000000UL, second);

		Calculation.RegisterFormulaForTest(9,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) => 16777217.0);
		TDamageParam wide = Param(9, 0, 7, 0, 1, 2);
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0 });
		double third = Calculation.CalculateFormula(wide, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T05c",
			"amount=16777217 extra=1 factor=1 => 16777217.0; premature float narrowing yields 16777216",
			0x4170000010000000UL, third);
	}

	// T06: exact Heal sign versus Cost / unknown calculation types, and the
	// numeric HealChange/HealedChange binding actually used by CalculateHeal.
	private static void T06_HealAndOtherCalculationTypes()
	{
		ResetAll();
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0, 0, 0, 0 });

		TDamageParam heal = Param(0, 1, 7, 0, 1, 2);
		heal.DamageData.CureBaseValueArray = new[] { 3 };
		heal.ExtraRate = 0.5f;
		double healResult = Calculation.CalculateFormula(heal, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T06a",
			"formulaType=0 calculateType=Heal rateLv=0 cureBase=3 extra=0.5 factor=1 => Ceiling(1.5)=2 then negated",
			0xC000000000000000UL, healResult);

		TDamageParam cost = Param(0, 2, 7, 0, 1, 2);
		cost.DamageData.CureBaseValueArray = new[] { 3 };
		cost.ExtraRate = 0.5f;
		double costResult = Calculation.CalculateFormula(cost, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T06b",
			"calculateType=Cost uses the HEAL computation but keeps the positive sign",
			0x4000000000000000UL, costResult);
		T.True("T06c", "Cost path read CureBaseValue exactly once",
			cost.DamageData.CureBaseValueReads == 1);

		TDamageParam unknown = Param(0, 99, 7, 0, 1, 2);
		unknown.DamageData.CureBaseValueArray = new[] { 3 };
		unknown.ExtraRate = 0.5f;
		double unknownResult = Calculation.CalculateFormula(unknown, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T06d",
			"calculateType=99 also uses the HEAL computation and keeps the positive sign",
			0x4000000000000000UL, unknownResult);

		TDamageParam bound = Param(0, 1, 7, 0, 1, 2);
		bound.DamageData.CureBaseValueArray = new[] { 3 };
		bound.ExtraRate = 0.5f;
		double boundResult = Calculation.CalculateFormula(bound, Payload(Snap((35, 10000f)), Snap()),
			false, 0.0, 0.0, 1.0, 1.0);
		T.Bits("T06e",
			"attacker EAttributeType 35 (HealChange) really feeds CalculateHeal: 3*(1+1)*0.5=3 then negated",
			0xC008000000000000UL, boundResult);
	}

	// T07: exception boundaries after and before the seed store; no rollback,
	// catch, or retry is added by the harness.
	private static void T07_ExceptionAfterSeedStore()
	{
		ResetAll();
		Calculation.RegisterFormulaForTest(7,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) => 1.0);
		TDamageParam upper = Param(7, 0, 7, 0, 1, 2);
		upper.DamageData.UpperThrows = true;
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0 });
		T.Throws<InvalidOperationException>("T07a",
			"FluentUpper hook throws after the provider result is stored",
			() => Calculation.CalculateFormula(upper, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0));
		T.True("T07b", "stored new seed survives the exception",
			upper.PeekSeed() == 0 && upper.SeedSets == 1);
		T.True("T07c", "no lower-bound or ExtraRate read after the throw",
			upper.DamageData.LowerReads == 0 && upper.ExtraRateReads == 0);

		ResetAll();
		Calculation.RegisterFormulaForTest(7,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) => 1.0);
		RandomSystem.ThrowOnCall = true;
		TDamageParam provider = Param(7, 0, 7, 0, 1, 2);
		T.Throws<InvalidOperationException>("T07d",
			"provider hook throws before the setter",
			() => Calculation.CalculateFormula(provider, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0));
		T.True("T07e", "old seed retained when the provider throws before the setter",
			provider.PeekSeed() == 2 && provider.SeedSets == 0);
		T.True("T07f", "no bound reads when the provider throws",
			provider.DamageData.UpperReads == 0 && provider.DamageData.LowerReads == 0);
	}

	// T08: repeated invocation, exact argument forwarding, and Ceiling boundaries.
	private static void T08_RepeatedInvocationAndForwarding()
	{
		ResetAll();
		TDamageParam param = Param(7, 0, 7, 0, 2, 2);
		param.DamageData.FluctuationUpperArray = new[] { 10001 };
		param.DamageData.FluctuationLowerArray = new[] { 10000 };
		param.Accumulation = 0.1f;
		param.ExtraRate = 1f;
		param.DamageData.FormulaParam1Array = new[] { 999, 11 };
		param.DamageData.FormulaParam2Array = new[] { 999, 12 };
		param.DamageData.FormulaParam3Array = new[] { 999, 13 };
		param.DamageData.FormulaParam4Array = new[] { 999, 14 };
		param.DamageData.FormulaParam5Array = new[] { 999, 15 };
		param.DamageData.FormulaParam6Array = new[] { 999, 16 };
		param.DamageData.FormulaParam7Array = new[] { 999, 17 };
		param.DamageData.FormulaParam8Array = new[] { 999, 18 };
		param.DamageData.FormulaParam9Array = new[] { 999, 19 };
		param.DamageData.FormulaParam10Array = new[] { 999, 20 };
		SnapshotPayload payload = Payload(Snap(), Snap());
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0, 7 });

		int calls = 0;
		bool argsOk = true;
		bool levelsOk = true;
		ulong accumulationBits = 0;
		Calculation.RegisterFormulaForTest(7,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) =>
			{
				calls++;
				bool expectedCritical = calls == 1;
				argsOk = argsOk
					&& object.ReferenceEquals(snap, payload)
					&& calculateType == ECalculationType.Hurt
					&& object.ReferenceEquals(input, param)
					&& level == 2
					&& isCritical == expectedCritical
					&& augment == (expectedCritical ? 5.0 : 0.0)
					&& amplify == (expectedCritical ? 6.0 : 0.0)
					&& multiRatio == (expectedCritical ? 2.0 : 1.0)
					&& gameplayRatio == (expectedCritical ? 0.5 : 0.25);
				accumulationBits = unchecked((ulong)BitConverter.DoubleToInt64Bits(accumulation));
				levelsOk = levelsOk
					&& parameters.Length == 10
					&& parameters[0] == 11.0 && parameters[1] == 12.0 && parameters[2] == 13.0
					&& parameters[3] == 14.0 && parameters[4] == 15.0 && parameters[5] == 16.0
					&& parameters[6] == 17.0 && parameters[7] == 18.0 && parameters[8] == 19.0
					&& parameters[9] == 20.0;
				return 1.0;
			});

		double first = Calculation.CalculateFormula(param, payload, true, 5.0, 6.0, 2.0, 0.5);
		double second = Calculation.CalculateFormula(param, payload, false, 0.0, 0.0, 1.0, 0.25);

		T.Bits("T08a",
			"first call oldSeed=2 next=0 upper=10001 lower=10000 => Ceiling(1.0002000331878662)=2",
			0x4000000000000000UL, first);
		T.Bits("T08b",
			"second call oldSeed=0 next=7 => Ceiling(1.0)=1",
			0x3FF0000000000000UL, second);
		T.True("T08c", "provider inputs [(2,1),(0,1)]",
			RandomSystem.Inputs.Count == 2
				&& RandomSystem.Inputs[0].Seed == 2
				&& RandomSystem.Inputs[0].Reason == 1
				&& RandomSystem.Inputs[1].Seed == 0
				&& RandomSystem.Inputs[1].Reason == 1);
		T.True("T08d", "final stored seed is 7", param.PeekSeed() == 7);
		T.True("T08e", "registered delegate invoked twice", calls == 2);
		T.True("T08f", "all forwarded arguments match the independently declared inputs", argsOk);
		T.True("T08g", "Accumulation is forwarded as the double promotion of float 0.1f",
			accumulationBits == 0x3FB99999A0000000UL);
		T.True("T08h", "ten level-evaluated parameters arrive in order 11..20", levelsOk);

		T.Bits("T08i", "callback=Math.BitDecrement(1) => Ceiling 1",
			0x3FF0000000000000UL, RoundCase(Math.BitDecrement(1.0)));
		T.Bits("T08j", "callback=1.0 => Ceiling 1",
			0x3FF0000000000000UL, RoundCase(1.0));
		T.Bits("T08k", "callback=Math.BitIncrement(1) => Ceiling 2",
			0x4000000000000000UL, RoundCase(Math.BitIncrement(1.0)));
		T.Bits("T08l", "callback=-1.25 with a custom registry => Ceiling -1, no Hurt clamp applied",
			0xBFF0000000000000UL, RoundCase(-1.25));
	}

	private static double RoundCase(double callbackValue)
	{
		ResetAll();
		Calculation.RegisterFormulaForTest(7,
			(snap, calculateType, input, level, isCritical, augment, amplify, accumulation, multiRatio, gameplayRatio, parameters) => callbackValue);
		TDamageParam param = Param(7, 0, 7, 0, 1, 2);
		RandomSystem.NextSeeds = new Queue<int>(new[] { 0 });
		return Calculation.CalculateFormula(param, Payload(Snap(), Snap()), false, 0.0, 0.0, 1.0, 1.0);
	}
}

internal static class T
{
	public static int Assertions;
	public static int Passed;
	public static int Failures;

	public static void Fail(string message)
	{
		Assertions++;
		Failures++;
		Console.WriteLine("  ASSERT FAIL " + message);
	}

	public static void Bits(string label, string vector, ulong expectedBits, double actual)
	{
		Assertions++;
		ulong actualBits = unchecked((ulong)BitConverter.DoubleToInt64Bits(actual));
		bool ok = actualBits == expectedBits;
		Console.WriteLine("  CASE " + label + " " + vector);
		Console.WriteLine("    expected=" + FromBits(expectedBits).ToString("R")
			+ " bits=0x" + expectedBits.ToString("X16")
			+ " observed=" + actual.ToString("R")
			+ " bits=0x" + actualBits.ToString("X16")
			+ (ok ? " MATCH" : " MISMATCH"));
		if (ok)
		{
			Passed++;
		}
		else
		{
			Failures++;
			Console.WriteLine("  ASSERT FAIL " + label + " bit pattern");
		}
	}

	public static void True(string label, string vector, bool condition)
	{
		Assertions++;
		Console.WriteLine("  CASE " + label + " " + vector);
		Console.WriteLine("    expected=true observed=" + (condition ? "true" : "false")
			+ (condition ? " MATCH" : " MISMATCH"));
		if (condition)
		{
			Passed++;
		}
		else
		{
			Failures++;
			Console.WriteLine("  ASSERT FAIL " + label + ": expected=true observed=false");
		}
	}

	public static void Throws<TEx>(string label, string vector, Action action) where TEx : Exception
	{
		Assertions++;
		Console.WriteLine("  CASE " + label + " " + vector);
		try
		{
			action();
			Failures++;
			Console.WriteLine("  ASSERT FAIL " + label + ": expected=" + typeof(TEx).Name + " observed=no-exception");
		}
		catch (Exception ex)
		{
			if (ex.GetType() == typeof(TEx))
			{
				Passed++;
				Console.WriteLine("    observed=" + ex.GetType().Name + " MATCH");
			}
			else
			{
				Failures++;
				Console.WriteLine("  ASSERT FAIL " + label + ": expected=" + typeof(TEx).Name
					+ " observed=" + ex.GetType().Name);
			}
		}
	}

	private static double FromBits(ulong bits)
	{
		return BitConverter.Int64BitsToDouble(unchecked((long)bits));
	}
}
